export function formatOrderDate(value){if(!value)return '—';const raw=String(value).trim();let d;const iso=raw.match(/^(\d{4})-(\d{2})-(\d{2})(?:$|T| )/),dmy=raw.match(/^(\d{1,2})[/. -](\d{1,2})[/. -](\d{4})$/);if(iso||dmy){const y=Number(iso?iso[1]:dmy[3]),m=Number(iso?iso[2]:dmy[1]),day=Number(iso?iso[3]:dmy[2]);d=new Date(Date.UTC(y,m-1,day));if(d.getUTCFullYear()!==y||d.getUTCMonth()!==m-1||d.getUTCDate()!==day)return '—'}else d=new Date(raw);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});}
